def sum_digits(n):
    s = 0
    while n:
        s += n % 10
        n //= 10
    return s

def solve_problem():
    n = 1
    while True:
        is_valid = True
        for k in range(n, n + 38):
            if sum_digits(k) % 11 == 0:
                is_valid = False
                break

        if is_valid:
            print(f"Found smallest n: {n}")
            return n

        n += 1

# We only search up to a reasonable limit to test feasibility, 
# based on typical Olympiad problem constraints.
# If it's too big, we assume it's too big for the intended scope.
try:
    n_solution = solve_problem()
    print(n_solution)
except RecursionError:
    print("Exceeded practical search limit.")

