def check_n(n):
    # Check if the product S(n)...S(n+37) is NOT a multiple of 11.
    # This is equivalent to checking if NO S(k) in the range is a multiple of 11.
    for k in range(n, n + 38):
        s_k = sum_digits(k)
        if s_k % 11 == 0:
            return False # Found a multiple of 11, so the product IS a multiple of 11.
    return True # No multiple of 11 found, so the product is NOT a multiple of 11.

